from puzzles import PUZZLES
from strands import StrandsPuzzle

HELP = ("Enter strand numbers in merge order, e.g. '1 2' or '3,1'. "
        "Commands: board | hint | found | quit")


def parse_indices(raw):
    tokens = raw.replace(",", " ").split()
    try:
        return [int(t) for t in tokens]
    except ValueError:
        return None


def play_puzzle(puzzle):
    print()
    print("=== {} ===".format(puzzle.title))
    print(HELP)
    while not puzzle.is_complete():
        print()
        print(puzzle.board())
        try:
            raw = input("Merge> ").strip().lower()
        except EOFError:
            return False
        if raw in ("q", "quit", "exit"):
            return False
        if raw in ("b", "board"):
            continue
        if raw in ("h", "hint"):
            print("Hint: " + puzzle.hint_text)
            continue
        if raw in ("f", "found"):
            print("Found so far: " + puzzle.found_display())
            continue
        if not raw:
            continue
        indices = parse_indices(raw)
        if indices is None:
            print("Could not read that. " + HELP)
            continue
        _, message = puzzle.attempt_merge(indices)
        print(message)
    print()
    print("*** {} complete! All strands correctly merged. ***".format(puzzle.title))
    print("Answers: " + ", ".join(puzzle.answers))
    return True


def main():
    print("=" * 54)
    print("                 S T R A N D S")
    print("       merge the strands, reveal the words")
    print("=" * 54)
    for data in PUZZLES:
        if not play_puzzle(StrandsPuzzle(data)):
            print("\nGame ended. Thanks for playing Strands!")
            return
        print("\nMoving on to the next puzzle...")
    print("\nAll puzzles solved - every strand correctly merged. Brilliant!")


if __name__ == "__main__":
    try:
        main()
    except (KeyboardInterrupt, EOFError):
        print("\nGame ended. Thanks for playing Strands!")
